/**
 * The types `charts/registry/` exports, in one place — so a neighbouring module finds the shape it
 * needs here instead of declaring its own under a second name.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    ChartCalculatorLink, SharedChartRendererKey, SharedChartDefinition
 * depends    —
 * used by    src/charts/index, src/charts/registry/calculator-links, src/charts/registry/data, src/charts/registry/index, src/charts/registry/mechanic-links, src/charts/tables/lookup
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */

// from calculator-links.ts

/** Which calculator produces one chart's numbers, and where its published rows live. */
export interface ChartCalculatorLink {
  /** The exported const holding the chart's published rows, if it has one. */
  data?: string
  /** Calculator handles that compute the same quantity. */
  calculators: readonly string[]
  /** Why there is no calculator, when there is none. */
  note?: string
}

// from data.ts

/** Which renderer draws a chart. One renderer may serve several paths. */
export type SharedChartRendererKey =
  | 'avg-bullets-to-stack-shock'
  | 'bonus-multipliers'
  | 'bot-upgrades'
  | 'card-mastery-cost-bonuses'
  | 'cfplus-rotation-rates'
  | 'cfplus-speed-rates'
  | 'chain-thunder-dmg-reduction'
  | 'elite-spawn-chance'
  | 'enemy-balance-mastery'
  | 'enemy-resistances'
  | 'eo-vs-sla-breakpoints'
  | 'gold-bot-vs-death-wave-uptime'
  | 'gt-combo-relative-income'
  | 'gt-combo-uptime-income'
  | 'gt-lab-milestones'
  | 'guild-box-rewards'
  | 'harmony-tree-upgrades'
  | 'lab-speed-multiplier'
  | 'module-substat-values'
  | 'perma-swamp-stone-costs'
  | 'pf-util-disso-gain-per-10-levels'
  | 'pf-util-disso-multiplier'
  | 'power-tree-upgrades'
  | 'recovery-package-drop-rates'
  | 'uw-plus-upgrades'
  | 'uw-stone-costs'
  | 'wave-accelerator-spawn-rates'
  | 'wave-skip-coin-boost'
  | 'wave-skip-multi-skip-chances'

export interface SharedChartDefinition {
  /** Stable address: `category:subcategory:item`. Unique. */
  pathId: string
  /** Which renderer draws it. NOT unique — several paths may share one. */
  rendererKey: SharedChartRendererKey
  /** Canonical English title. Localisation is the consumer's job. */
  title: string
  /** Canonical English description. */
  description: string
  /** Exported image filename, for consumers that publish stills. */
  fileName: string
  /** Accent colour used when the chart is rendered. */
  colorHex: string
  /** Attribution, where a community member produced the chart. */
  creatorCredit?: string
}
